#define _POSIX_C_SOURCE 200809L
#include <pthread.h>

static pthread_barrier_t phase;                 /* auto-resets each generation */
void *worker(void *arg) {
    for (int step = 0; step < steps; step++) {
        compute_step(arg, step);
        int r = pthread_barrier_wait(&phase);   /* init: pthread_barrier_init */
        if (r == PTHREAD_BARRIER_SERIAL_THREAD) merge_partials();  /* leader */
    }
    return NULL;
}
